// Shapes of the public identifiers, the same as protocol 0.1 (packages/protocol/src/objects.js).

export const UID_RE = /^rvr_[A-Za-z0-9_-]{22}$/
export const ID_RE = /^ob_[A-Za-z0-9_-]{43}$/
export const TOPIC_RE = /^[a-z0-9][a-z0-9-]{1,23}$/

export const isUid = (x: unknown): boolean => typeof x === 'string' && UID_RE.test(x)
export const isObjectId = (x: unknown): boolean => typeof x === 'string' && ID_RE.test(x)

/**
 * Demonstration ids: they have the shape of a real id (to pass the same checkers), but
 * start with DEMO and end in zeros, so nobody confuses them with an id generated by the network.
 */
export function demoId(prefix: 'rvr' | 'ob', label: string): string {
  const size = prefix === 'rvr' ? 22 : 43
  const core = `DEMO${label}`.replace(/[^A-Za-z0-9]/g, '')
  return `${prefix}_${core.padEnd(size, '0').slice(0, size)}`
}
